// HasBundle applies the HasEdge predicate on the "bundle" edge.
func HasBundle() predicate.BundleSubscriptionHistory {
	return predicate.BundleSubscriptionHistory(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, BundleTable, BundleColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBundleWith applies the HasEdge predicate on the "bundle" edge with a given conditions (other predicates).
func HasBundleWith(preds ...predicate.Bundles) predicate.BundleSubscriptionHistory {
	return predicate.BundleSubscriptionHistory(func(s *sql.Selector) {
		step := newBundleStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

